    public Optional<Integer> prodSigns(List<Integer> arr) {

        if (arr.size() == 0) {
            return Optional.empty();
        }
        int product = 1;
        int sum = 0;
        for (int i = 0; i < arr.size(); i++) {
            int num = arr.get(i);
            if (num < 0) {
                product *= -1;
            } else if (num > 0) {
                product *= 1;
            }
            sum += Math.abs(num);
        }
        return Optional.of(product * sum);
    }
}

