    public int modp(int n, int p) {

        if (n == 0) return 1;
        int res = 1;
        int base = 2;
        while (n > 0) {
            if ((n & 1) == 1) res = (res * base) % p;
            base = (base * base) % p;
            n >>= 1;
        }
        return res;
    }
}

