        char[] wordChars = word.toCharArray();
        int wordLength = wordChars.length;
        int closestVowelIndex = -1;
        int closestVowelDistance = Integer.MAX_VALUE;
        for (int i = wordLength - 1; i >= 0; i--) {
            if (isVowel(wordChars[i], vowels)) {
                if (i > 0 && i < wordLength - 1) {
                    if (isConsonant(wordChars[i - 1], vowels) && isConsonant(wordChars[i + 1], vowels)) {
                        int distance = wordLength - i - 1;
                        if (distance < closestVowelDistance) {
                            closestVowelDistance = distance;
                            closestVowelIndex = i;
                        }
                    }
                }
            }
        }
        if (closestVowelIndex == -1) {
            return "";
        }
        return String.valueOf(wordChars[closestVowelIndex]);
    }
}

